def update_all_supercar_cases(apps, schema_editor):
    Case = apps.get_model('cases', 'Case')
    Item = apps.get_model('cases', 'Item')
    CaseItem = apps.get_model('cases', 'CaseItem')

    # Step 1: Upsert all unique items first
    items_map = {}
    for case_slug, case_info in CASES_CANONICAL.items():
        for it_data in case_info['items']:
            nm = it_data['name']
            if nm in items_map:
                continue
            val = Decimal(str(it_data['value']))
            item = Item.objects.filter(name=nm).first()
            if not item:
                item = Item.objects.create(
                    name=nm,
                    weapon_type=it_data.get('weapon_type', 'Vehicle'),
                    skin_name=it_data.get('skin_name', nm),
                    rarity=it_data.get('rarity', 'covert'),
                    rarity_color=it_data.get('rarity_color', '#eb4b4b'),
                    value=val,
                    image=it_data.get('image', ''),
                    game='PUBG'
                )
            else:
                update_fields = []
                if item.value != val:
                    item.value = val
                    update_fields.append('value')
                if not item.image or 'placeholder' in str(item.image) or item.image != it_data['image']:
                    item.image = it_data['image']
                    update_fields.append('image')
                if item.rarity != it_data.get('rarity', item.rarity):
                    item.rarity = it_data['rarity']
                    update_fields.append('rarity')
                if item.rarity_color != it_data.get('rarity_color', item.rarity_color):
                    item.rarity_color = it_data['rarity_color']
                    update_fields.append('rarity_color')
                if update_fields:
                    item.save(update_fields=list(set(update_fields)))
            items_map[nm] = item

